/**
 * Writes `src/terminal/xterm/assets.generated.ts`: xterm.js, its CSS, the search and Unicode 11
 * addons and the JetBrains Mono font as strings. The terminal page inlines them, so it works
 * offline and loads nothing from the network. The app never runs this code itself: only the web
 * view of the terminal does. Run it after a change of an `@xterm/*` version:
 *
 *   node scripts/gen-xterm-assets.js
 *
 * A Jest test (`assets.test.ts`) fails when the file differs from what this script makes.
 */
const fs = require("fs");
const path = require("path");

const OUT = path.join(__dirname, "..", "src", "terminal", "xterm", "assets.generated.ts");

/** The folder of an installed package (from its main file, so package `exports` do not matter). */
function pkgRoot(name) {
  let dir = path.dirname(require.resolve(name));
  while (!fs.existsSync(path.join(dir, "package.json"))) dir = path.dirname(dir);
  return dir;
}

function read(file) {
  return fs.readFileSync(file, "utf8");
}

/** Script text that is safe inside a `<script>` element, with no source map link. */
function script(file) {
  return read(file)
    .replace(/\n\/\/# sourceMappingURL=.*$/m, "")
    .replace(/<\/script/gi, "<\\/script");
}

/** The first lines of a license file: the name and the copyright. */
function licenseHead(file) {
  return read(file)
    .split("\n")
    .filter((l) => l.trim())
    .slice(0, 3)
    .map((l) => l.trim());
}

function buildAssets() {
  const xterm = pkgRoot("@xterm/xterm");
  const search = pkgRoot("@xterm/addon-search");
  const unicode = pkgRoot("@xterm/addon-unicode11");
  const fonts = pkgRoot("@expo-google-fonts/jetbrains-mono");
  const version = (dir) => JSON.parse(read(path.join(dir, "package.json"))).version;
  const font = (rel) => fs.readFileSync(path.join(fonts, rel)).toString("base64");
  const versions = {
    xterm: version(xterm),
    search: version(search),
    unicode11: version(unicode),
    jetbrainsMono: version(fonts),
  };
  const out = [
    "// Generated by app/scripts/gen-xterm-assets.js. Do not edit: run `node scripts/gen-xterm-assets.js` in app/.",
    `// @xterm/xterm ${versions.xterm}, @xterm/addon-search ${versions.search}, @xterm/addon-unicode11 ${versions.unicode11}:`,
    ...licenseHead(path.join(xterm, "LICENSE")).map((l) => `//   ${l}`),
    `// JetBrains Mono (@expo-google-fonts/jetbrains-mono ${versions.jetbrainsMono}): SIL Open Font License 1.1.`,
    "",
    `export const XTERM_VERSIONS = ${JSON.stringify(versions)} as const;`,
    `export const XTERM_CSS = ${JSON.stringify(read(path.join(xterm, "css", "xterm.css")))};`,
    `export const XTERM_JS = ${JSON.stringify(script(path.join(xterm, "lib", "xterm.js")))};`,
    `export const SEARCH_JS = ${JSON.stringify(script(path.join(search, "lib", "addon-search.js")))};`,
    `export const UNICODE11_JS = ${JSON.stringify(script(path.join(unicode, "lib", "addon-unicode11.js")))};`,
    `export const FONT_REGULAR_B64 = ${JSON.stringify(font("400Regular/JetBrainsMono_400Regular.ttf"))};`,
    `export const FONT_BOLD_B64 = ${JSON.stringify(font("700Bold/JetBrainsMono_700Bold.ttf"))};`,
    "",
  ];
  return out.join("\n");
}

module.exports = { buildAssets, OUT };

if (require.main === module) {
  fs.writeFileSync(OUT, buildAssets());
  console.log(`wrote ${path.relative(process.cwd(), OUT)}`);
}
